{
  "role_title": "Senior backend engineer",
  "candidate_jurisdictions": ["US-NY", "US-CA", "DE"],
  "redaction": {
    "version": "1.3.0",
    "stripped_attributes": ["name", "photo", "email-handle", "date-of-birth-and-age", "graduation-years", "address-below-city", "gender-markers-and-pronouns", "nationality-and-visa-status", "marital-and-parental-status", "protected-class-associations"],
    "unit_tested": true,
    "fixture_set_path": "hiring/redaction/fixtures/",
    "human_sample_inspected_per_release": true,
    "sample_size_per_release": 20
  },
  "rubric": {
    "version": "2.1",
    "hash": "sha256:4c2a9b1e7f3d6a8c0b5e2f9d1a7c3e6b8f0d2a4c6e8b1d3f5a7c9e1b3d5f7a9c",
    "written_before_first_score": true,
    "first_score_at": "2026-02-10",
    "criteria": [
      {"name": "correctness", "job_requirement": "Ships services that pass the integration suite", "anchors": {"low": "Solution fails the provided test cases or does not run", "mid": "Passes the provided tests; misses at least one stated edge case", "high": "Passes provided tests and handles every stated edge case with tests of its own"}},
      {"name": "design clarity", "job_requirement": "Designs modules other engineers can extend", "anchors": {"low": "Single function with mixed concerns; no explanation of trade-offs", "mid": "Reasonable separation; trade-offs partly explained", "high": "Clear module boundaries with the trade-offs and alternatives stated"}}
    ]
  },
  "proxy_review": {
    "reviewed_on": "2026-02-03",
    "reviewed_by": "dei:rkim",
    "proxy_terms_found": [],
    "evidence_url": "https://hr.example.com/reviews/rubric-2.1-proxy-review"
  },
  "calibration": {
    "sample_source": "real-applicant-pool",
    "sample_size": 30,
    "human_reviewers": 2,
    "statistic": "weighted-kappa",
    "threshold": 0.65,
    "threshold_set_before_run": true,
    "result": 0.71,
    "run_url": "https://hr.example.com/calibration/backend-2026-02",
    "passed": true,
    "run_at": "2026-02-07"
  },
  "adverse_impact": {
    "self_id_store": "hris.eeo_self_id",
    "self_id_store_separate_from_scoring": true,
    "hold_threshold": 0.8,
    "per_stage": [
      {"stage": "take-home forwarded to hiring manager", "groups": [{"group": "A", "selection_rate": 0.52}, {"group": "B", "selection_rate": 0.47}, {"group": "C", "selection_rate": 0.49}], "min_ratio": 0.9, "on_hold": false},
      {"stage": "advanced to onsite", "groups": [{"group": "A", "selection_rate": 0.31}, {"group": "B", "selection_rate": 0.27}, {"group": "C", "selection_rate": 0.29}], "min_ratio": 0.87, "on_hold": false}
    ],
    "table_url": "https://hr.example.com/adverse-impact/backend-2026-q1"
  },
  "human_of_record": {
    "auto_reject_filter_present": false,
    "decision_carries_role_handle": true,
    "reviewer_inputs": ["redacted-document", "score-with-reasons"],
    "reviewers": ["em:jdoe", "em:apatel"]
  },
  "legal": {
    "applicable_law": "nyc-ll-144",
    "notice_text_url": "https://careers.example.com/aedt-notice",
    "notice_lead_business_days": 10,
    "bias_audit": {"conducted_on": "2025-11-15", "independent": true, "summary_url": "https://careers.example.com/aedt-bias-audit-2025", "auditor": "Example Audit LLP"}
  },
  "audit_log": {
    "fields": ["submission_hash", "redacted_text", "model_id", "prompt_hash", "rubric_version", "score_with_reasons", "human_decision"],
    "retention_months": 24,
    "retention_basis": "29 CFR 1602.14 one-year floor; company policy two years",
    "queryable_per_candidate": true,
    "storage": "hiring.screen_audit table, candidate_id index"
  },
  "pinned_tuple": {
    "model_id": "claude-sonnet-4-5-20250929",
    "prompt_hash": "sha256:8e1f0a3c5b7d9f2e4a6c8b0d1f3e5a7c9b1d3f5e7a9c2b4d6f8a0c1e3b5d7f9a",
    "rubric_version": "2.1",
    "redaction_version": "1.3.0"
  },
  "evidence": [
    "https://hr.example.com/calibration/backend-2026-02",
    "https://hr.example.com/reviews/rubric-2.1-proxy-review",
    "https://careers.example.com/aedt-bias-audit-2025",
    "https://hr.example.com/adverse-impact/backend-2026-q1"
  ]
}

